427	/* The mobile menu button ships as a filled circle with a shadow. The system
428	   has no filled circles and no shadows outside true overlays, so it becomes a
429	   32px hairline square. 32px is under the 44px minimum touch target, so the
430	   hit area is expanded past the visual box with a pseudo-element. */
431	.sl-menu-button {
432	  border: 1px solid var(--sl-color-hairline-light);
433	  border-radius: var(--bl-radius-1);
434	  background-color: var(--sl-color-bg);
435	  color: var(--sl-color-gray-1);
436	  box-shadow: none;
437	}
438	
439	.sl-menu-button:hover {
440	  background-color: var(--sl-color-gray-6);
441	  border-color: var(--sl-color-gray-4);
442	  color: var(--sl-color-white);
443	}
444	
445	.sl-menu-button:has(~ :popover-open) {
446	  background-color: var(--sl-color-gray-6);
447	  border-color: var(--sl-color-gray-4);
448	  color: var(--sl-color-white);
449	  box-shadow: none;
450	}
451	
452	/* 32px box, 44px target: the pseudo-element is the thing the finger hits. */
453	.sl-menu-button::after {
454	  content: '';
455	  position: absolute;
456	  inset: calc((var(--sl-menu-button-size) - 2.75rem) / 2);
457	}
458	
459	/* Below the sidebar breakpoint the search control is an icon button; the design
460	   draws it as a 32px hairline square, again with a 44px hit area. */
461	@media (max-width: 50rem) {
462	  site-search button[data-open-modal] {
463	    position: relative;
464	    width: var(--sl-menu-button-size);
465	    height: var(--sl-menu-button-size);
466	    justify-content: center;
467	    padding: 0;
468	    border: 1px solid var(--sl-color-hairline-light);
469	    border-radius: var(--bl-radius-1);
470	    background-color: transparent;
471	    color: var(--sl-color-gray-1);
472	  }
473	
474	  site-search button[data-open-modal]::after {
475	    content: '';
476	    position: absolute;
477	    inset: calc((var(--sl-menu-button-size) - 2.75rem) / 2);
478	  }
479	
480	  site-search button[data-open-modal] svg {
481	    font-size: 1rem;
482	  }
483	}
484	
485	/* --- Sidebar ------------------------------------------------------------ */
486	.sidebar-content {
487	  padding: 2rem var(--sl-sidebar-pad-x);
488	}
489	
490	/* 28px between top-level groups */
491	.sidebar-content .top-level > li + li {
