501	}
502	
503	.sidebar-content a {
504	  font-size: var(--sl-text-sm);
505	  padding: 0.375rem 0.5rem;
506	  border-radius: var(--bl-radius-2);
507	}
508	
509	/* Guarded against `[aria-current]` so the brass current-page pill survives a
510	   hover — an unlayered `a:hover` would otherwise outrank Starlight's rule. */
511	.sidebar-content a:not([aria-current='page']):is(:hover, :focus-visible) {
512	  background-color: var(--sl-color-gray-6);
513	  color: var(--sl-color-white);
514	}
