/* The system has exactly two surfaces — warm ebony and cream — so the stock
   three-option auto/light/dark <select> becomes a two-state toggle. The stored
   key and the `data-theme` attribute stay Starlight's, so ThemeProvider's
   no-FOUC inline script keeps working unchanged. */
import { Icon } from '@astrojs/starlight/components';
---

<starlight-theme-select>
	<button type="button" class="theme-toggle">
		<Icon name="moon" class="icon-dark" size="1rem" />
		<Icon name="sun" class="icon-light" size="1rem" />
		<span class="sr-only">{Astro.locals.t('themeSelect.accessibleLabel')}</span>
	</button>
</starlight-theme-select>

<script>
	/** Key in `localStorage` to store colour theme preference at — Starlight's own. */
	const storageKey = 'starlight-theme';

	const currentTheme = (): 'dark' | 'light' =>
		document.documentElement.dataset.theme === 'light' ? 'light' : 'dark';

	class StarlightThemeSelect extends HTMLElement {
		constructor() {
			super();
			const button = this.querySelector('button');
			if (!button) return;
			const label = () => {
				// Name the destination, not the state: this is a control, not a status.
				button.setAttribute(
					'aria-label',
					currentTheme() === 'dark' ? 'Use the light theme' : 'Use the dark theme'
				);
			};
			label();
			button.addEventListener('click', () => {
				const next = currentTheme() === 'dark' ? 'light' : 'dark';
				document.documentElement.dataset.theme = next;
				try {
					localStorage.setItem(storageKey, next);
				} catch {}
				label();
			});
		}
	}
	customElements.define('starlight-theme-select', StarlightThemeSelect);
</script>

<style>
	@layer starlight.core {
		.theme-toggle {
			position: relative;
