/* Frame Job's own components in the Boppa Llewyn theme (boppa-llewyn.css, which loads first and
   holds every token used here): hairline boxes instead of shadows and accent bars, mono uppercase
   eyebrows for labels, and the system's small radii. Unlayered, like the theme. */

/* ---- Screens: both looks are in the page, the theme shows one. ---- */

.fj-shot {
  margin-block: 1.5rem;
}

.fj-shot img {
  display: block;
  width: 100%;
  height: auto;
  border: 1px solid var(--sl-color-hairline-light);
  border-radius: var(--bl-radius-1);
}

.fj-shot figcaption {
  margin-top: 0.5rem;
  color: var(--sl-color-gray-3);
  font-size: var(--sl-text-sm);
}

:root[data-theme='light'] .fj-shot .fj-dark,
:root:not([data-theme='light']) .fj-shot .fj-light {
  display: none;
}

/* ---- Keys, as the app prints them: ⌘T. The theme styles the key cap itself. ---- */

.sl-markdown-content kbd {
  white-space: nowrap;
}

/* ---- At a glance: a hairline box, its labels mono eyebrows. ---- */

.fj-glance {
  display: grid;
  grid-template-columns: max-content 1fr;
  align-items: baseline;
  gap: 0.5rem 1.5rem;
  margin-block: 1.5rem;
  padding: 1rem 1.25rem;
  background-color: var(--sl-color-gray-6);
  border: 1px solid var(--sl-color-hairline-light);
  border-radius: var(--bl-radius-2);
  font-size: var(--sl-text-sm);
  color: var(--sl-color-gray-1);
}

.fj-glance dt {
  margin: 0;
  font-family: var(--sl-font-mono);
  font-weight: 500;
  font-size: 0.75rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--sl-color-gray-3);
}

.fj-glance dd {
  display: flex;
  flex-wrap: wrap;
  gap: 0.25rem 1rem;
  margin: 0;
}

.fj-glance strong {
  font-weight: 600;
  color: var(--sl-color-white);
}

.fj-glance code {
  font-size: 0.8125rem;
  background-color: var(--sl-color-bg-inline-code);
  border-radius: var(--bl-radius-1);
  padding: 0.0625rem 0.3125rem;
}

/* ---- The feature index ---- */

.fj-filter {
  position: sticky;
  top: calc(var(--sl-nav-height) + 0.5rem);
  z-index: 2;
  display: flex;
  align-items: center;
  gap: 1rem;
  margin-block: 1rem 2rem;
  padding: 0.625rem 0.75rem;
  background-color: var(--sl-color-gray-6);
  border: 1px solid var(--sl-color-hairline-light);
  border-radius: var(--bl-radius-2);
}

.fj-filter input {
  flex: 1;
  min-width: 0;
  padding: 0.4375rem 0.625rem;
  font: inherit;
  font-size: var(--sl-text-sm);
  color: var(--sl-color-white);
  background-color: var(--sl-color-bg);
  border: 1px solid var(--sl-color-hairline-light);
  border-radius: var(--bl-radius-1);
}

.fj-filter input::placeholder {
  color: var(--sl-color-gray-3);
}

.fj-filter output {
  font-family: var(--sl-font-mono);
  font-size: 0.75rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--sl-color-gray-3);
  white-space: nowrap;
}

.fj-features {
  table-layout: fixed;
}

.fj-features th:nth-child(1) {
  width: 26%;
}

.fj-features th:nth-child(3) {
  width: 30%;
}

.fj-features td {
  overflow-wrap: anywhere;
}

.fj-features td.fj-where {
  color: var(--sl-color-gray-2);
  font-size: 0.8125rem;
}

.fj-section[hidden],
.fj-features tr[hidden] {
  display: none;
}

